uint32_t crc = 0xffffffff;
for (size_t i = 0; i < n; i++) {
    crc = kByteExtensionTable[static_cast<unsigned char>(data[i]) ^ (crc & 0xff)] ^
          (crc >> 8);
}
return crc ^ 0xffffffff;

